(() => {
  'use strict';

  // Compatibility ceiling for packets generated by the historical 3.3.1
  // organizer (up to nine summaries plus twelve core memories).
  const MAX_TARGETS = 24;
  const MAX_PACKET_BYTES = 2 * 1024 * 1024;
  const MAX_TARGET_TEXT = 5000;
  const CONTEXT_DIMENSIONS = new Set(['importance', 'participants', 'stage', 'scope', 'basis']);
  const clean = (value, max = 12000) => String(value || '').trim().slice(0, max);
  const cleanId = (value, label) => {
    const result = clean(value, 120);
    if (!/^[a-zA-Z0-9_-]+$/.test(result)) throw new Error(`${label}格式无效。`);
    return result;
  };

  function normalizeClarificationHints(value) {
    if (value === undefined) return [];
    if (!Array.isArray(value) || value.length > 6 || value.some(item => typeof item !== 'string' || item.length > 500)) throw new Error('补充提示格式无效：最多 6 个问题，每个最多 500 字。');
    return value.map(item => clean(item.replace(/\u0000/g, ''), 500)).filter(Boolean);
  }

  function normalizeContextQuestions(value, itemIds) {
    if (!Array.isArray(value) || !value.length || value.length > 5) throw new Error('背景核对需要 1–5 个问题。');
    const contextId = value => {
      if (typeof value !== 'string' || !/^[a-zA-Z0-9_-]{1,120}$/.test(value)) throw new Error('背景问题或选项编号格式无效。');
      return value;
    };
    const seen = new Set();
    const text = (value, limit, required = true) => {
      if (typeof value !== 'string' || value.length > limit || (required && !value.trim())) throw new Error('背景问题文字格式或长度无效。');
      return clean(value, limit);
    };
    return value.map(question => {
      const fields = ['id', 'dimension', 'prompt', 'groupLabel', 'memberIds', 'options', 'allowDetail'];
      if (!question || typeof question !== 'object' || Array.isArray(question) || Object.keys(question).some(key => !fields.includes(key))) throw new Error('背景问题包含无效字段。');
      const id = contextId(question.id);
      if (seen.has(id) || !CONTEXT_DIMENSIONS.has(question.dimension) || question.allowDetail !== true) throw new Error('背景问题编号、类别或补充设置无效。');
      seen.add(id);
      if (!Array.isArray(question.memberIds) || !question.memberIds.length || question.memberIds.length > 12) throw new Error('背景问题缺少有效关联记忆。');
      const memberIds = question.memberIds.map(contextId);
      if (new Set(memberIds).size !== memberIds.length || memberIds.some(value => !itemIds.has(value))) throw new Error('背景问题引用了重复或未知记忆。');
      if (!Array.isArray(question.options) || question.options.length < 2 || question.options.length > 16) throw new Error('背景问题选项数量无效。');
      const optionIds = new Set();
      const options = question.options.map(option => {
        if (!option || typeof option !== 'object' || Array.isArray(option) || Object.keys(option).some(key => !['id', 'label'].includes(key))) throw new Error('背景问题选项格式无效。');
        const optionId = contextId(option.id);
        if (optionIds.has(optionId)) throw new Error('背景问题存在重复选项。');
        optionIds.add(optionId);
        return { id: optionId, label: text(option.label, 200) };
      });
      if (!optionIds.has('unknown') || !optionIds.has('other')) throw new Error('背景问题必须允许“不确定”和“都不符合”。');
      return { id, dimension: question.dimension, prompt: text(question.prompt, 500), groupLabel: text(question.groupLabel, 200, false), memberIds, options, allowDetail: true };
    });
  }

  function normalizeTarget(entry, kind, index) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) throw new Error(`第 ${index + 1} 个核对项无效。`);
    const id = cleanId(entry.id, '核对项编号');
    if (entry.confirmationStatus !== undefined && entry.confirmationStatus !== 'pending') throw new Error(`核对项 ${id} 的确认状态无效。`);
    if (entry.eventGroup !== undefined && (kind !== 'item' || typeof entry.eventGroup !== 'string' || entry.eventGroup.length > 160)) throw new Error(`核对项 ${id} 的事件分组无效。`);
    const fullText = String(entry.text || '').trim();
    if (fullText.length > MAX_TARGET_TEXT) throw new Error(`核对项 ${id} 超过 ${MAX_TARGET_TEXT} 字，请先精简内容。`);
    const text = clean(fullText, MAX_TARGET_TEXT);
    if (!text) throw new Error(`核对项 ${id} 没有内容。`);
    const section = ['relationship', 'interaction', 'companion', 'boundaries', 'events'].includes(entry.section) ? entry.section : (kind === 'summary' ? 'relationship' : 'events');
    const shared = { id, text, section, ...(entry.confirmationStatus === 'pending' ? { confirmationStatus: 'pending' } : {}), ...(entry.evidenceSnippet ? { evidenceSnippet: clean(entry.evidenceSnippet, 1000) } : {}) };
    return kind === 'summary'
      ? { ...shared, label: clean(entry.label || '整体判断', 120) }
      : { ...shared, type: clean(entry.type || '整理条目', 120), memberCount: Math.max(1, Math.min(99, Number(entry.memberCount) || 1)), ...(entry.eventGroup ? { eventGroup: clean(entry.eventGroup.replace(/\u0000/g, ''), 160) } : {}) };
  }

  function normalizePacket(input) {
    if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('核对包格式无效。');
    const contextual = input.schemaVersion === 'memorbit-participant-review/2';
    if (!contextual && input.schemaVersion !== 'memorbit-participant-review/1') throw new Error('核对包版本不受支持。');
    if (contextual ? input.reviewMode !== 'contextual' || input.reviewScope !== 'supplemental' : input.reviewMode !== undefined || input.contextQuestions !== undefined) throw new Error('核对模式与版本不匹配，请重新生成核对包。');
    if (input.reviewScope !== undefined && !['normal', 'supplemental'].includes(input.reviewScope)) throw new Error('核对包范围无效。');
    const summary = Array.isArray(input.summary) ? input.summary.map((entry, index) => normalizeTarget(entry, 'summary', index)) : [];
    const items = Array.isArray(input.items) ? input.items.map((entry, index) => normalizeTarget(entry, 'item', index)) : [];
    if (!summary.length && !items.length && input.reviewScope !== 'supplemental') throw new Error('核对包没有可核对内容。');
    if (summary.length + items.length > MAX_TARGETS) throw new Error(`核对项不能超过 ${MAX_TARGETS} 条。`);
    if (input.reviewScope === 'supplemental' && (items.length > 12 || summary.length > 2)) throw new Error('补充核对每轮最多 12 条候选和 2 条关系或相处判断。');
    const seen = new Set();
    [...summary, ...items].forEach(target => {
      if (seen.has(target.id)) throw new Error(`核对项编号重复：${target.id}`);
      seen.add(target.id);
      if (contextual) delete target.evidenceSnippet;
    });
    return {
      schemaVersion: contextual ? 'memorbit-participant-review/2' : 'memorbit-participant-review/1',
      ...(contextual ? { reviewMode: 'contextual', contextQuestions: normalizeContextQuestions(input.contextQuestions, new Set(items.map(item => item.id))) } : {}),
      ...(input.reviewScope !== undefined ? { reviewScope: input.reviewScope } : {}),
      reviewId: cleanId(input.reviewId, '核对编号'),
      packetVersion: clean(input.packetVersion, 40) || '1',
      packetHash: clean(input.packetHash, 160),
      participantAlias: clean(input.participantAlias, 100) || '未提供',
      createdAt: clean(input.createdAt, 80),
      expiresAt: clean(input.expiresAt, 80),
      title: clean(input.title, 160) || '整理好的档案内容核对',
      intro: clean(input.intro, 1000),
      consentVersion: clean(input.consentVersion, 80) || '1.0',
      consentText: clean(input.consentText, 2000),
      subjects: {
        user: clean(input.subjects?.user, 100) || '用户',
        companion: clean(input.subjects?.companion, 100) || 'AI 伴侣'
      },
      verdictOptions: ['accurate', 'needs_change', 'uncertain'],
      summary,
      items,
      ...(input.clarificationHints !== undefined ? { clarificationHints: normalizeClarificationHints(input.clarificationHints) } : {}),
      suggestedGaps: Array.isArray(input.suggestedGaps)
        ? input.suggestedGaps.map(value => clean(value, 180)).filter(Boolean).slice(0, 2)
        : [],
      privacy: {
        includesRawChat: false,
        includesScreenshots: false,
        includesSourceFilenames: false,
        note: clean(input.privacy?.note, 500)
      }
    };
  }

  const bytesToBase64 = bytes => {
    let binary = '';
    for (let offset = 0; offset < bytes.length; offset += 32768) {
      binary += String.fromCharCode(...bytes.subarray(offset, offset + 32768));
    }
    return btoa(binary);
  };

  async function sha256(bytes) {
    if (!globalThis.crypto?.subtle) throw new Error('当前浏览器不支持安全摘要，请改用最新版 Edge、Chrome 或 Safari。');
    const digest = new Uint8Array(await globalThis.crypto.subtle.digest('SHA-256', bytes));
    return {
      hex: [...digest].map(byte => byte.toString(16).padStart(2, '0')).join(''),
      base64: bytesToBase64(digest)
    };
  }

  async function readAsset(url) {
    let response;
    try {
      response = await fetch(url, { cache: 'no-store', credentials: 'same-origin' });
    } catch (error) {
      if (location.protocol === 'file:') throw new Error('直接双击内部站无法读取核对模板，请从已经部署的 HTTPS 网站生成核对页。');
      throw error;
    }
    if (!response.ok) throw new Error(`无法读取核对页模板（${response.status}）。`);
    return response.text();
  }

  async function build(packetInput, options = {}) {
    const packet = normalizePacket(packetInput);
    const baseUrl = new URL(options.baseUrl || 'participant-review/', document.baseURI);
    const [template, cssSource, jsSource] = await Promise.all([
      readAsset(new URL('review.html?v=20260914-context-b05', baseUrl)),
      readAsset(new URL('review.css?v=20260914-context-b05', baseUrl)),
      readAsset(new URL('review.js?v=20260914-context-b05', baseUrl))
    ]);
    const packetBytes = new TextEncoder().encode(JSON.stringify(packet));
    if (packetBytes.byteLength > MAX_PACKET_BYTES) throw new Error('精简核对内容超过 2 MB，请减少核对条目后重试。');
    const packetDigest = await sha256(packetBytes);
    const css = cssSource.replace(/<\/style/gi, '<\\/style');
    const js = jsSource.replace(/<\/script/gi, '<\\/script');
    const [cssDigest, jsDigest] = await Promise.all([
      sha256(new TextEncoder().encode(css)),
      sha256(new TextEncoder().encode(js))
    ]);
    const csp = [
      "default-src 'none'",
      `script-src 'sha256-${jsDigest.base64}'`,
      `style-src 'sha256-${cssDigest.base64}'`,
      "connect-src 'none'", "img-src 'none'", "font-src 'none'", "media-src 'none'",
      "object-src 'none'", "frame-src 'none'", "worker-src 'none'", "base-uri 'none'", "form-action 'none'"
    ].join('; ');
    let html = template
      .replace(/<meta http-equiv="Content-Security-Policy" content="[^"]*">/i, `<meta http-equiv="Content-Security-Policy" content="${csp}">`)
      .replace(/<link rel="stylesheet" href="review\.css(?:\?[^\"]*)?">/i, `<style>${css}</style>`)
      .replace(/\s*<script src="review\.js(?:\?[^\"]*)?" defer><\/script>/i, '')
      .replace(/<title>[^<]*<\/title>/i, '<title>星迹 · 用户档案核对</title>');
    const embedded = `<meta name="memorbit-review-packet-sha256" content="${packetDigest.hex}">\n<template id="embeddedReviewPacket">${bytesToBase64(packetBytes)}</template>\n<script>${js}</script>`;
    html = html.replace('</body>', `${embedded}\n</body>`);
    return { html, packet, packetSha256: packetDigest.hex };
  }

  globalThis.MemorbitReviewSingleFile = Object.freeze({ build, normalizePacket });
})();
